        collect(){const p=this.player,mag=this.skillBonus?.magnetRadius|| (this.magnetTime>0?190:0);for(const c of this.data.coins){const dist=Math.hypot(p.x+p.w/2-c.x,p.y+p.h/2-c.y);if(!c.got&&mag&&dist<mag){c.x+=(p.x+p.w/2-c.x)*.12;c.y+=(p.y+p.h/2-c.y)*.12}if(!c.got&&dist<60){c.got=true;this.burst(c.x,c.y,'#ffd34d',6);const coinValue=this.isBonus?this.bonusCoinMultiplier:1;this.scoreCoins+=coinValue;MC.state.dailyEvent?.('coins',coinValue);this.lifeCoinCounter+=coinValue;const lifeGoal=MC.state.data.settings.extraLifeCoins||100;if(this.lifeCoinCounter>=lifeGoal){this.lifeCoinCounter-=lifeGoal;MC.state.data.profile.lifeCoinProgress=this.lifeCoinCounter;MC.state.addLife(1);this.flash('¡VIDA EXTRA!')}else{MC.state.data.profile.lifeCoinProgress=this.lifeCoinCounter;MC.state.save()}this.updateHUD()}}for(const c of this.data.cubes){const dist=Math.hypot(p.x+p.w/2-c.x,p.y+p.h/2-c.y);if(!c.got&&mag&&dist<mag){c.x+=(p.x+p.w/2-c.x)*.09;c.y+=(p.y+p.h/2-c.y)*.09}if(!c.got&&dist<70){c.got=true;this.burst(c.x,c.y,this.theme.accent,10);if(c.objective!==false)this.collectedCubes++;this.flash(c.objective===false?'Cubo extra encontrado':`Cubo ${this.collectedCubes}/${this.data.objective.type==='collect'?this.data.objective.target:this.data.cubes.filter(x=>x.objective!==false).length}`);this.updateHUD()}}for(const k of this.data.keys){if(k.got)continue;const kw=k.w||48,kh=k.h||48,kcx=k.x+kw/2,kcy=k.y+kh/2,pcx=p.x+p.w/2,pcy=p.y+p.h/2,dist=Math.hypot(pcx-kcx,pcy-kcy),near=Math.abs(pcx-kcx)<92&&Math.abs(pcy-kcy)<118,box={x:k.x-18,y:k.y-18,w:kw+36,h:kh+36};if(hit(p,box)||near||dist<88){k.got=true;this.keysOwned.add(k.link||'A');for(const d of this.data.doors)if((d.link||'A')===(k.link||'A'))d.open=true;this.burst(kcx,kcy,'#ffd34d',12);this.flash('🔑 Llave obtenida · puerta vinculada abierta',1900);this.updateHUD()}}}
    chestNear(ch){const p=this.player;if(!p||!ch||ch.opened)return false;const cx=ch.x+(ch.w||58)/2,cy=ch.y+(ch.h||45)/2,px=p.x+p.w/2,py=p.y+p.h/2;return Math.abs(cx-px)<128&&Math.abs(cy-py)<126}
