      for(const z of this.data.windZones||[]){const x=z.x-cam,y=this.sy(z.y);if(x+z.w<0||x>W)continue;c.save();c.fillStyle='rgba(104,225,255,.07)';c.fillRect(x,y,z.w,z.h);c.strokeStyle='rgba(155,242,255,.45)';c.lineWidth=3;for(let yy=y+55;yy<y+z.h;yy+=70){for(let xx=x+35;xx<x+z.w-35;xx+=95){const dir=Math.sign(z.fx||1);c.beginPath();c.moveTo(xx,yy);c.lineTo(xx+dir*38,yy);c.lineTo(xx+dir*27,yy-8);c.moveTo(xx+dir*38,yy);c.lineTo(xx+dir*27,yy+8);c.stroke()}}c.restore()}
